import{_ as a,a0 as d,w as p,s as r,I as n,x as i,a1 as e,A as o,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"调整你的 Git 配置以适应多个用户 ID 的需要 | LCTT x X-CMD","titleTemplate":false,"description":"调整你的 Git 配置以适应多个用户 ID 的需要 | LCTT (202011) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"调整你的 Git 配置以适应多个用户 ID 的需要 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"调整你的 Git 配置以适应多个用户 ID 的需要 | LCTT (202011) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202011/20201105 Tweak your Git config for multiple user IDs","title":"调整你的 Git 配置以适应多个用户 ID 的需要","tag":"202011","desc":""},"relativePath":"202011/20201105 Tweak your Git config for multiple user IDs.md","filePath":"[post].md"}'),u={name:"202011/20201105 Tweak your Git config for multiple user IDs.md"};function g(f,t,m,k,T,b){const s=d("Link");return p(),r("div",null,[t[31]||(t[31]=n("h1",{id:"调整你的-git-配置以适应多个用户-id-的需要",tabindex:"-1"},[i("调整你的 Git 配置以适应多个用户 ID 的需要 "),n("a",{class:"header-anchor",href:"#调整你的-git-配置以适应多个用户-id-的需要","aria-label":"Permalink to “调整你的 Git 配置以适应多个用户 ID 的需要”"},"​")],-1)),t[32]||(t[32]=n("blockquote",null,[n("p",null,"可以使用相同的机器用于工作和个人的 Git 提交，而无需手动重置你的配置。")],-1)),t[33]||(t[33]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202011/12/013805t4u4nu57rc6ur7nt.jpg",alt:""})],-1)),n("p",null,[t[1]||(t[1]=i("Git 的 ",-1)),e(s,{href:"https://git-scm.com/docs/git-config"},{default:o(()=>[...t[0]||(t[0]=[i("git config",-1)])]),_:1}),t[2]||(t[2]=i(" 命令可以让你为 Git 设置仓库或全局选项。它有很多选项，其中的一个选项 ",-1)),t[3]||(t[3]=n("code",null,"includeIf",-1)),t[4]||(t[4]=i(" 在你使用在 Git 时有双重角色时非常方便，比如说，你既是全职的开发者，又在业余时间为开源项目做贡献。在这种情况下，大多数人都不想为两个角色使用一个共同的配置，或者，至少，他们肯定希望保持配置的某些部分是不同的，尤其是当他们在两个角色中使用同一台计算机时。",-1))]),t[34]||(t[34]=l(`<p>我的情况就是这样，所以我在 Git 配置中保留了两组不同的邮件 ID。这样一来，在我工作场所的项目仓库中提交的内容就会使用我办公室的邮件 ID，而在我个人 GitHub 帐户中提交的内容则使用我个人的邮件 ID。</p><p>以下是我的全局配置（维护在 <code>$HOME/.gitconfig</code>）中的一个片段，我将在下文中介绍。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[includeIf &quot;gitdir:~/priv_scm/&quot;]</span></span>
<span class="line"><span>        path = ~/priv_scm/.gitconfig</span></span>
<span class="line"><span>[includeIf &quot;gitdir:~/work_scm/&quot;]</span></span>
<span class="line"><span>        path = ~/work_scm/.gitconfig</span></span></code></pre></div><h3 id="什么是-includeif" tabindex="-1">什么是 includeIf？ <a class="header-anchor" href="#什么是-includeif" aria-label="Permalink to “什么是 includeIf？”">​</a></h3><p><code>includeIf.condition.path</code> 变量，是 <code>include</code> 配置指令的一部分，允许你有条件地设置自定义配置。同时，自定义配置的路径也可以作为指令的一部分来设置。</p>`,5)),n("p",null,[t[6]||(t[6]=i("这个指令支持三个关键字：",-1)),t[7]||(t[7]=n("code",null,"gitdir",-1)),t[8]||(t[8]=i("、",-1)),t[9]||(t[9]=n("code",null,"gitdir/I",-1)),t[10]||(t[10]=i(" 和 ",-1)),t[11]||(t[11]=n("code",null,"onbranch",-1)),t[12]||(t[12]=i("。我将简单解释一下 ",-1)),t[13]||(t[13]=n("code",null,"gitdir",-1)),t[14]||(t[14]=i("，我在上面的代码片段中使用了它。你可以在",-1)),e(s,{href:"https://git-scm.com/docs/git-config#_conditional_includes"},{default:o(()=>[...t[5]||(t[5]=[i("文档",-1)])]),_:1}),t[15]||(t[15]=i("中了解其他两个关键词。",-1))]),t[35]||(t[35]=l(`<p>在 <code>includeIf</code> 指令中使用 <code>gitdir</code> 关键字会对模式进行条件检查。根据规则，如果当前工作目录与 <code>gitdir</code> 中指定的目录模式相匹配，那么它就会从给定的路径中选取配置。我将在配置片段上应用这个规则来展示它是如何被应用的。</p><p>在配置片段中，你可以看到一个简单的模式，<code>~/</code>，它与 <code>gitdir</code> 关键字一起使用。这个模式会被存储在 <code>$HOME</code> 环境变量中的值所替代。</p><h3 id="如何使用它" tabindex="-1">如何使用它 <a class="header-anchor" href="#如何使用它" aria-label="Permalink to “如何使用它”">​</a></h3><p>如果你使用同一个系统在 GitHub 或 GitLab 上的开源项目上工作，并在工作中提交到 Git 仓库，你可以有两个顶级目录，比如 <code>$HOME/priv_scm</code> 和 <code>$HOME/work_scm</code>。在这两个目录中，你可以有两个单独的 <code>.gitconfig</code> 文件，其中包含与你的 <code>user.name</code> 和 <code>user.email</code> 相关的设置。然而，它们也可以包含存储在 <code>$HOME</code> 的全局 <code>.gitconfig</code> 中，它可以保存两个环境通用的所有自定义项。</p><p>这里是一个例子 <code>$HOME/priv_scm/.gitconfig</code> 的片段：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat $HOME/priv_scm/.gitconfig</span></span>
<span class="line"><span>[user]</span></span>
<span class="line"><span>    name  = Ramanathan Muthiah</span></span>
<span class="line"><span>    email = &amp;lt;personal-mailid-goes-here&amp;gt;</span></span></code></pre></div><p>有了这个配置，你就可以切换目录，并开始在开源项目上工作，而无需手动重置一些与 Git 相关的配置。这些更改会在主 <code>.gitconfig</code> 中借助 <code>includeIf</code> 条件指令自动处理。</p><h3 id="git-小贴士" tabindex="-1">Git 小贴士 <a class="header-anchor" href="#git-小贴士" aria-label="Permalink to “Git 小贴士”">​</a></h3><p>希望这个小贴士能帮助你组织 Git 项目。你最喜欢的 Git 小贴士是什么？请在评论中分享吧！</p><hr>`,10)),n("p",null,[t[17]||(t[17]=i("via: ",-1)),e(s,{href:"https://opensource.com/article/20/10/git-config"},{default:o(()=>[...t[16]||(t[16]=[i("https://opensource.com/article/20/10/git-config",-1)])]),_:1})]),n("p",null,[t[22]||(t[22]=i("作者：",-1)),e(s,{href:"https://opensource.com/users/muthiahramanathan"},{default:o(()=>[...t[18]||(t[18]=[i("Ramanathan M",-1)])]),_:1}),t[23]||(t[23]=i(" 选题：",-1)),e(s,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[19]||(t[19]=[i("lujun9972",-1)])]),_:1}),t[24]||(t[24]=i(" 译者：",-1)),e(s,{href:"https://github.com/geekpi"},{default:o(()=>[...t[20]||(t[20]=[i("geekpi",-1)])]),_:1}),t[25]||(t[25]=i(" 校对：",-1)),e(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[21]||(t[21]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[28]||(t[28]=i("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[26]||(t[26]=[i("LCTT",-1)])]),_:1}),t[29]||(t[29]=i(" 原创编译，",-1)),e(s,{href:"https://linux.cn/"},{default:o(()=>[...t[27]||(t[27]=[i("Linux中国",-1)])]),_:1}),t[30]||(t[30]=i(" 荣誉推出",-1))])])}const c=a(u,[["render",g]]);export{C as __pageData,c as default};
